begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
set local role authenticated;
set local request.jwt.claim.sub = '00000000-0000-4000-8000-000000000001';
select ok(private.has_permission('members:manage','10000000-0000-4000-8000-000000000001'),'owner manages only their salon');
select ok(not private.has_permission('members:manage'),'global profile role does not grant member management');
select ok(not private.has_permission('payroll:manage','10000000-0000-4000-8000-000000000002'),'owner cannot manage another salon payroll');
select is_empty($$select id from public.organizations where id='10000000-0000-4000-8000-000000000002'$$,'other salon is undiscoverable');
select is_empty($$select id from public.customers where organization_id='10000000-0000-4000-8000-000000000002'$$,'customer contacts are tenant isolated');
select is_empty($$select id from public.services where organization_id='10000000-0000-4000-8000-000000000002'$$,'service catalog is tenant isolated');
select is_empty($$select id from public.staff_profiles where organization_id='10000000-0000-4000-8000-000000000002'$$,'staff are tenant isolated');
select is_empty($$select staff_id from public.staff_compensation where organization_id='10000000-0000-4000-8000-000000000002'$$,'compensation is tenant isolated');
select is_empty($$select id from public.appointments where organization_id='10000000-0000-4000-8000-000000000002'$$,'appointments are tenant isolated');
select throws_ok($$select public.save_booking('10000000-0000-4000-8000-000000000002','{}')$$,'42501',null,'RPC cannot bypass tenant authorization');
select throws_ok($$insert into public.customers(organization_id,name,status) values('10000000-0000-4000-8000-000000000002','Attack','lead')$$,'42501',null,'cross-tenant insert denied');
select is_empty($$update public.customers set name='Attack' where organization_id='10000000-0000-4000-8000-000000000002' returning id$$,'cross-tenant update denied');
select is_empty($$delete from public.customers where organization_id='10000000-0000-4000-8000-000000000002' returning id$$,'cross-tenant delete denied');
select throws_ok($$insert into public.customers(name,status) values('Unscoped','lead')$$,'23502',null,'unscoped customer creation forbidden');
select throws_ok($$insert into public.staff_services values('10000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000003')$$,'42501',null,'direct mutation grants are absent');
reset role;
select throws_ok($$insert into public.staff_services values('10000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000003')$$,'23503',null,'composite FK rejects cross-salon service even for trusted writes');
select ok((select bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),'all public tables enable RLS');
set local role authenticated;
set local request.jwt.claim.sub = '00000000-0000-4000-8000-000000000002';
select ok(private.has_permission('appointments:manage','10000000-0000-4000-8000-000000000001'),'manager can schedule appointments');
select ok(private.has_permission('attendance:manage','10000000-0000-4000-8000-000000000001'),'manager can review attendance');
select ok(not private.has_permission('payroll:manage','10000000-0000-4000-8000-000000000001'),'manager cannot approve payroll');
select is_empty($$select * from public.staff_compensation$$,'manager cannot read pay configuration');
select throws_ok($$select public.calculate_payroll('10000000-0000-4000-8000-000000000001','2026-10-01','2026-10-15')$$,'42501',null,'manager cannot call financial operations directly');
set local request.jwt.claim.sub = '00000000-0000-4000-8000-000000000003';
select is_empty($$select id from public.customers$$,'staff cannot read customer directory');
select results_eq($$select id from public.staff_profiles$$,array['40000000-0000-4000-8000-000000000001'::uuid],'staff can read only own employee record');
select is_empty($$select * from public.staff_compensation$$,'staff cannot read salary configuration');
select is_empty($$select id from public.appointments where staff_id<>'40000000-0000-4000-8000-000000000001'$$,'staff can read assigned appointments only');
select throws_ok($$select commission_value from public.appointment_services$$,'42501',null,'booking commission rules are confidential');
select lives_ok($$select public.punch_attendance('10000000-0000-4000-8000-000000000001','in')$$,'staff can clock in');
select throws_ok($$select public.punch_attendance('10000000-0000-4000-8000-000000000001','in')$$,'P0001','You are already clocked in.','duplicate punch rejected');
select lives_ok($$select public.punch_attendance('10000000-0000-4000-8000-000000000001','out')$$,'staff can clock out');
select throws_ok($$select public.punch_attendance('10000000-0000-4000-8000-000000000002','in')$$,'42501',null,'staff cannot punch in another salon');
select * from finish();
rollback;
